/* C API of the Rust port of `rational.c`, generated by everything-rust. */
#ifndef RATIONAL_RS_H
#define RATIONAL_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

typedef struct { int num; int den; } AVRational;

int av_reduce(int *dst_num, int *dst_den, int64_t num, int64_t den, int64_t max);
AVRational av_mul_q(AVRational b, AVRational c);
AVRational av_div_q(AVRational b, AVRational c);
AVRational av_add_q(AVRational b, AVRational c);
AVRational av_sub_q(AVRational b, AVRational c);
AVRational av_d2q(double d, int max);
int av_nearer_q(AVRational q, AVRational q1, AVRational q2);
uint32_t av_q2intfloat(AVRational q);

/* The same functions under `everything_rust_` names, for shadow runs. */
int everything_rust_av_reduce(int *dst_num, int *dst_den, int64_t num, int64_t den, int64_t max);
AVRational everything_rust_av_mul_q(AVRational b, AVRational c);
AVRational everything_rust_av_div_q(AVRational b, AVRational c);
AVRational everything_rust_av_add_q(AVRational b, AVRational c);
AVRational everything_rust_av_sub_q(AVRational b, AVRational c);
AVRational everything_rust_av_d2q(double d, int max);
int everything_rust_av_nearer_q(AVRational q, AVRational q1, AVRational q2);
uint32_t everything_rust_av_q2intfloat(AVRational q);

#endif /* RATIONAL_RS_H */
